source('mp10_hypothesis_followup_v1/scripts/common.R');suppressPackageStartupMessages(library(fgsea));plan<-old('model_plan.tsv')[kind=='Epi'];sr<-rd('signature_registry.tsv');branches<-c('FA_SYNTH_DESAT','STEROL_SYNTH','LIPID_UPTAKE_TRANSPORT','PRENYLATION');out<-list()
for(i in seq_len(nrow(plan))){r<-plan[i];f<-file.path(OLD,'tables/de',paste0(r$model_id,'.tsv.gz'));if(!file.exists(f))next;d<-fread(f);d[,stat:=sign(logFC)*sqrt(pmax(F,0))];d<-d[is.finite(stat)];setorder(d,-stat,gene)
 for(mask in c('Full','M20')){ii<-which(sr$mask==mask&sr$signature%in%branches);sets<-lapply(split(sr$gene[ii],sr$signature[ii]),unique);dd<-if(mask=='M20')d[!gene%in%M20]else d;stats<-setNames(dd$stat,dd$gene);coverage<-data.table(pathway=branches,n_covered=vapply(branches,function(x)length(intersect(sets[[x]],names(stats))),integer(1)));valid<-coverage[n_covered>=15&n_covered<=500,pathway];rr<-data.table()
 if(length(valid)){for(budget in c(10000,100000)){set.seed(123);rr<-as.data.table(fgseaMultilevel(sets[valid],stats,minSize=15,maxSize=500,nPermSimple=budget,nproc=1,eps=1e-10,scoreType='std'));if(!any(!is.finite(rr$pval)|(!is.finite(rr$log2err)&rr$pval>1e-10)))break};rr[,leadingEdge:=vapply(leadingEdge,paste,collapse=';',FUN.VALUE=character(1))]}
 if(nrow(rr))rr<-merge(coverage,rr,by='pathway',all.x=TRUE)else rr<-coverage[,`:=`(pval=NA_real_,NES=NA_real_,leadingEdge=NA_character_)];rr[,`:=`(model_id=r$model_id,High=r$target,min_cells=r$min_cells,patient=r$patient,subset=r$subset,omit_dataset=r$omit_dataset,only_dataset=r$only_dataset,primary=r$primary,mask=mask)];rr[,status:=ifelse(is.finite(pval),'completed','not_evaluable')];rr[,reason:=ifelse(n_covered<15,'below_frozen_GSEA_minSize15',ifelse(!is.finite(pval),'numerical_estimate_unresolved',''))];out[[paste(i,mask)]]<-rr
 };cat('BRANCH',i,nrow(plan),'\n')
}
z<-rbindlist(out,fill=TRUE);z[,FDR_family:=paste('paired_branches',mask,min_cells,patient,subset,omit_dataset,only_dataset,sep='__')];z[,q_fixed12:=p.adjust(pval,'BH',n=12),by=FDR_family];z[,planned_n:=12];put(z,'paired_branch_gsea.tsv.gz');cat('BRANCH COMPLETE\n')
